// APP STATE
let cart = JSON.parse(localStorage.getItem('db_cart')||'[]');
let wishlist = JSON.parse(localStorage.getItem('db_wish')||'[]');
let orders = JSON.parse(localStorage.getItem('db_orders')||'[]');
let currentPage = 1;
const PER_PAGE = 20;

// ============================================================
// UTILS
// ============================================================
function saveCart(){localStorage.setItem('db_cart',JSON.stringify(cart));updateCartBadge();}
function saveWish(){localStorage.setItem('db_wish',JSON.stringify(wishlist));}
function saveOrders(){localStorage.setItem('db_orders',JSON.stringify(orders));}
function updateCartBadge(){document.getElementById('cartBadge').textContent=cart.reduce((s,i)=>s+i.qty,0)||0;}
function formatPrice(n){return '₹'+n.toLocaleString('en-IN');}
function stars(r){let s='';for(let i=1;i<=5;i++)s+=i<=Math.floor(r)?'★':'☆';return s;}
function isWished(id){return wishlist.includes(id);}

function showToast(msg,type='success'){
  const c=document.getElementById('toastContainer');
  const t=document.createElement('div');
  t.className='toast '+(type||'');
  t.innerHTML=(type==='success'?'<i class="bi bi-check-circle-fill me-2"></i>':type==='error'?'<i class="bi bi-exclamation-triangle-fill me-2"></i>':'<i class="bi bi-info-circle-fill me-2"></i>')+msg;
  c.appendChild(t);
  setTimeout(()=>t.style.opacity='0',2800);
  setTimeout(()=>t.remove(),3200);
}

function showPage(id){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  const pg=document.getElementById('page-'+id);
  if(pg){pg.classList.add('active');window.scrollTo({top:0,behavior:'smooth'});}
  // Re-render dynamic pages
  if(id==='cart')renderCart();
  if(id==='wishlist')renderWishlist();
  if(id==='orders')renderOrders();
  if(id==='checkout')renderCheckoutSummary();
  if(id==='products'){currentPage=1;renderProducts();}
}

function filterByCategory(cat){
  showPage('products');
  document.getElementById('catFilter').value=cat;
  renderProducts();
}

// ============================================================
// PRODUCT CARD
// ============================================================
function prodCard(p, showRemove=false){
  const w=isWished(p.id);
  const inCart=cart.find(i=>i.id===p.id);
  return `
  <div class="prod-card" onclick="openProduct(${p.id})">
    <div class="prod-img">
      ${p.rating>=4.8?'<span class="prod-badge"><i class="bi bi-star-fill me-1 text-warning"></i> Top Rated</span>':''}
      <button class="prod-wish ${w?'active':''}" onclick="event.stopPropagation();toggleWish(${p.id},this)" aria-label="Wishlist">
        <svg width="16" height="16" fill="${w?'currentColor':'none'}" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg>
      </button>
      <img src="media/products/prod_${p.id}_1.jpg" alt="${p.name}" style="width:100%;height:100%;object-fit:cover;display:block" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"><div style="display:none; font-size:3rem; height:180px; width:100%; align-items:center; justify-content:center; color:var(--saffron); background:linear-gradient(135deg,var(--cream),var(--cream-dark));"><i class="bi ${CAT_ICON[p.category]||'bi-bag'}"></i></div>
    </div>
    <div class="prod-body">
      <div class="prod-cat">${p.category}</div>
      <div class="prod-name">${p.name}</div>
      <div class="prod-rating"><span class="stars">${stars(p.rating)}</span>${p.rating} (${Math.floor(p.stock*0.6)} reviews)</div>
      <div class="prod-price-row">
        <span class="prod-price">${formatPrice(p.price)}</span>
        <button class="add-btn" onclick="event.stopPropagation();addToCart(${p.id})">${inCart?'Added':'+ Cart'}</button>
      </div>
      <div class="prod-stock">✓ ${p.stock} in stock</div>
    </div>
  </div>`;
}

// ============================================================
// WISHLIST TOGGLE
// ============================================================
function toggleWish(id, btn){
  if(wishlist.includes(id)){
    wishlist=wishlist.filter(i=>i!==id);
    if(btn){btn.classList.remove('active');btn.querySelector('svg').setAttribute('fill','none');}
    showToast('Removed from wishlist','');
  } else {
    wishlist.push(id);
    if(btn){btn.classList.add('active');btn.querySelector('svg').setAttribute('fill','currentColor');}
    showToast('Added to wishlist');
  }
  saveWish();
}

// ============================================================
// ADD TO CART
// ============================================================
function addToCart(id){
  const p=PRODUCTS.find(x=>x.id===id);
  if(!p)return;
  const existing=cart.find(i=>i.id===id);
  if(existing){existing.qty++;showToast(`${p.name} quantity updated`);}
  else{cart.push({id,qty:1});showToast(`${p.name} added to cart!`);}
  saveCart();
  // update any visible add button
  document.querySelectorAll('.add-btn').forEach(b=>{
    if(b.closest('.prod-card')&&b.closest('.prod-card').getAttribute('onclick')===`openProduct(${id})`)
      b.textContent='Added';
  });
}

// ============================================================
// PRODUCTS PAGE
// ============================================================
function getFilteredProducts(){
  const search=(document.getElementById('prodSearch')?.value||'').toLowerCase();
  const cat=document.getElementById('catFilter')?.value||'';
  const sort=document.getElementById('sortFilter')?.value||'';
  const price=document.getElementById('priceFilter')?.value||'';

  let arr=PRODUCTS.filter(p=>{
    if(cat&&p.category!==cat)return false;
    if(search&&!p.name.toLowerCase().includes(search)&&!p.details.toLowerCase().includes(search)&&!p.category.toLowerCase().includes(search))return false;
    if(price){
      const[mn,mx]=price.split('-').map(Number);
      if(mx){if(p.price<mn||p.price>mx)return false;}
      else{if(p.price<mn)return false;}
    }
    return true;
  });

  if(sort==='price-asc')arr.sort((a,b)=>a.price-b.price);
  else if(sort==='price-desc')arr.sort((a,b)=>b.price-a.price);
  else if(sort==='rating')arr.sort((a,b)=>b.rating-a.rating);
  else if(sort==='az')arr.sort((a,b)=>a.name.localeCompare(b.name));
  return arr;
}

function renderProducts(){
  const arr=getFilteredProducts();
  const total=arr.length;
  const pages=Math.ceil(total/PER_PAGE);
  if(currentPage>pages)currentPage=1;
  const slice=arr.slice((currentPage-1)*PER_PAGE,currentPage*PER_PAGE);

  document.getElementById('resultsCount').textContent=`${total} products found`;
  document.getElementById('productsGrid').innerHTML=slice.map(p=>prodCard(p)).join('');

  // Pagination
  let pgHtml='';
  if(pages>1){
    pgHtml+=`<button class="page-btn wide" onclick="changePage(${currentPage-1})" ${currentPage===1?'disabled':''}>← Prev</button>`;
    for(let i=1;i<=Math.min(pages,7);i++){
      if(i===1||i===pages||Math.abs(i-currentPage)<=2)
        pgHtml+=`<button class="page-btn ${i===currentPage?'active':''}" onclick="changePage(${i})">${i}</button>`;
      else if(Math.abs(i-currentPage)===3)pgHtml+=`<button class="page-btn" disabled>…</button>`;
    }
    pgHtml+=`<button class="page-btn wide" onclick="changePage(${currentPage+1})" ${currentPage===pages?'disabled':''}>Next →</button>`;
  }
  document.getElementById('pagination').innerHTML=pgHtml;

  // Populate cat filter if empty
  const catSel=document.getElementById('catFilter');
  if(catSel.options.length<=1){
    const cats=[...new Set(PRODUCTS.map(p=>p.category))].sort();
    cats.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;catSel.appendChild(o);});
  }
}

function changePage(n){
  const arr=getFilteredProducts();
  const pages=Math.ceil(arr.length/PER_PAGE);
  if(n<1||n>pages)return;
  currentPage=n;
  renderProducts();
  document.getElementById('page-products')?.scrollIntoView({behavior:'smooth'});
}

function handleNavSearch(){
  const v=document.getElementById('navSearchInput').value;
  if(v.length>1){
    showPage('products');
    document.getElementById('prodSearch').value=v;
    currentPage=1;
    renderProducts();
  }
}
function navSearchFocus(){if(document.getElementById('navSearchInput').value.length>1)showPage('products');}

