function changeQty(delta){
  detailQty=Math.max(1,detailQty+delta);
  const el=document.getElementById('detailQtyNum');
  if(el)el.textContent=detailQty;
}

function addToCartQty(id){
  const p=PRODUCTS.find(x=>x.id===id);
  const existing=cart.find(i=>i.id===id);
  if(existing){existing.qty+=detailQty;}
  else{cart.push({id,qty:detailQty});}
  saveCart();
  showToast(`${p.name} (×${detailQty}) added to cart!`);
}

function toggleWishDetail(id){
  const btn=document.getElementById('detailWishBtn');
  toggleWish(id,null);
  if(btn)btn.innerHTML=isWished(id)?'❤️ Wishlist':'🤍 Wishlist';
}

// ============================================================
// CART
// ============================================================
function renderCart(){
  const el=document.getElementById('cartItems');
  const smEl=document.getElementById('cartSummary');
  if(!cart.length){
    el.innerHTML=`<div class="empty-state"><div class="empty-emoji" style="color:var(--text3);"><i class="bi bi-cart-x"></i></div><div class="empty-title">Your cart is empty</div><p class="empty-sub">Add some amazing Indian products!</p><button class="btn-hero btn-hero-primary" onclick="showPage('products')">Shop Now →</button></div>`;
    smEl.innerHTML='<p style="color:var(--text3);font-size:0.9rem">No items yet.</p>';
    return;
  }
  let subtotal=0;
  el.innerHTML=cart.map(item=>{
    const p=PRODUCTS.find(x=>x.id===item.id);
    if(!p)return '';
    subtotal+=p.price*item.qty;
    return `<div class="cart-item">
      <div class="cart-item-emoji" style="padding:0;overflow:hidden;"><img src="media/products/prod_${p.id}_1.jpg" alt="${p.name}" style="width:100%;height:100%;object-fit:cover" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"><div style="display:none;font-size:1.8rem;height:100%;width:100%;align-items:center;justify-content:center;color:var(--saffron)"><i class="bi ${CAT_ICON[p.category]||'bi-bag'}"></i></div></div>
      <div class="cart-item-info">
        <div class="cart-item-name">${p.name}</div>
        <div class="cart-item-cat">${p.category}</div>
        <div class="cart-item-price">${formatPrice(p.price)} × ${item.qty} = ${formatPrice(p.price*item.qty)}</div>
      </div>
      <div class="cart-item-actions">
        <button class="cart-remove" onclick="removeFromCart(${p.id})" title="Remove">✕</button>
        <div style="display:flex;gap:8px;align-items:center">
          <button class="qty-btn" onclick="updateCartQty(${p.id},-1)">−</button>
          <span class="qty-num">${item.qty}</span>
          <button class="qty-btn" onclick="updateCartQty(${p.id},1)">+</button>
        </div>
      </div>
    </div>`;
  }).join('');

  const delivery=subtotal>=999?0:99;
  smEl.innerHTML=`
    <div class="summary-row"><span>Subtotal (${cart.reduce((s,i)=>s+i.qty,0)} items)</span><span>${formatPrice(subtotal)}</span></div>
    <div class="summary-row"><span>Delivery</span><span>${delivery===0?'<span style="color:var(--green)">FREE</span>':formatPrice(delivery)}</span></div>
    <div class="summary-row"><span>GST (5%)</span><span>${formatPrice(Math.round(subtotal*0.05))}</span></div>
    <div class="summary-row total"><span>Total</span><span>${formatPrice(subtotal+delivery+Math.round(subtotal*0.05))}</span></div>`;
}

function removeFromCart(id){
  cart=cart.filter(i=>i.id!==id);
  saveCart();renderCart();
}

function updateCartQty(id,delta){
  const item=cart.find(i=>i.id===id);
  if(!item)return;
  item.qty=Math.max(1,item.qty+delta);
  saveCart();renderCart();
}

// ============================================================
// CHECKOUT
// ============================================================
function renderCheckoutSummary(){
  let subtotal=cart.reduce((s,i)=>{const p=PRODUCTS.find(x=>x.id===i.id);return s+(p?p.price*i.qty:0);},0);
  const delivery=subtotal>=999?0:99;
  const gst=Math.round(subtotal*0.05);
  const total=subtotal+delivery+gst;
  document.getElementById('checkoutSummary').innerHTML=`
    ${cart.slice(0,3).map(i=>{const p=PRODUCTS.find(x=>x.id===i.id);return p?`<div style="display:flex;justify-content:space-between;font-size:0.85rem;color:var(--text2);margin-bottom:6px"><span>${PROD_EMOJI(p)} ${p.name} ×${i.qty}</span><span>${formatPrice(p.price*i.qty)}</span></div>`:''}).join('')}
    ${cart.length>3?`<p style="font-size:0.8rem;color:var(--text3);margin-bottom:6px">+${cart.length-3} more items</p>`:''}
    <div class="summary-row" style="border-top:1.5px solid var(--border);padding-top:8px;margin-top:8px"><span>Subtotal</span><span>${formatPrice(subtotal)}</span></div>
    <div class="summary-row"><span>Delivery</span><span>${delivery===0?'FREE':formatPrice(delivery)}</span></div>
    <div class="summary-row"><span>GST (5%)</span><span>${formatPrice(gst)}</span></div>
    <div class="summary-row total"><span>Total</span><span style="color:var(--saffron)">${formatPrice(total)}</span></div>`;
}

function selectPay(n){
  for(let i=1;i<=4;i++)document.getElementById('payOpt'+i)?.classList.remove('selected');
  document.getElementById('payOpt'+n)?.classList.add('selected');
}

function placeOrder(){
  if(!cart.length){showToast('Your cart is empty!','error');return;}
  const subtotal=cart.reduce((s,i)=>{const p=PRODUCTS.find(x=>x.id===i.id);return s+(p?p.price*i.qty:0);},0);
  const order={
    id:'DB'+Date.now(),
    date:new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}),
    items:[...cart],
    total:subtotal+Math.round(subtotal*0.05)+(subtotal>=999?0:99),
    status:'Processing'
  };
  orders.unshift(order);
  saveOrders();
  cart=[];saveCart();
  document.getElementById('successOrderNum').textContent='Order ID: '+order.id;
  showPage('success');
}

