// ORDERS
// ============================================================
function renderOrders(){
  const el=document.getElementById('ordersList');
  if(!orders.length){
    el.innerHTML=`<div class="empty-state"><div class="empty-emoji" style="color:var(--text3);"><i class="bi bi-box-arrow-in-down"></i></div><div class="empty-title">No orders yet</div><p class="empty-sub">Your order history will appear here.</p><button class="btn-hero btn-hero-primary" onclick="showPage('products')">Start Shopping →</button></div>`;
    return;
  }
  const statuses=['Processing','Shipped','Delivered'];
  el.innerHTML=orders.map(o=>{
    const items=o.items.map(i=>{const p=PRODUCTS.find(x=>x.id===i.id);return p?p.name:'';}).filter(Boolean);
    const sCls=o.status==='Delivered'?'status-delivered':o.status==='Shipped'?'status-shipped':'status-processing';
    return `<div class="order-card">
      <div class="order-header">
        <div><div class="order-id">${o.id}</div><div class="order-date"><i class='bi bi-calendar-event me-1'></i> ${o.date}</div></div>
        <span class="order-status ${sCls}">${o.status}</span>
      </div>
      <div class="order-items-preview">
        ${items.slice(0,3).map(n=>`<span class="order-item-chip">${n}</span>`).join('')}
        ${items.length>3?`<span class="order-item-chip">+${items.length-3} more</span>`:''}
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div class="order-total">${formatPrice(o.total)}</div>
        <button onclick="showToast('Tracking coming soon!')" style="background:none;border:1.5px solid var(--saffron);color:var(--saffron);padding:6px 14px;border-radius:50px;font-family:Nunito,sans-serif;font-weight:700;cursor:pointer;font-size:0.85rem">Track Order</button>
      </div>
    </div>`;
  }).join('');
}

